"""matplotlib.texmanager — TeX rendering stubs."""

class TexManager:
    @staticmethod
    def get_rgba_preview(tex, fontsize=12, dpi=150, rgb=(0, 0, 0)):
        import numpy as np
        return np.zeros((10, 10, 4), dtype=np.uint8)

    @staticmethod
    def get_text_width_height_descent(tex, fontsize, renderer=None):
        return (0, 0, 0)

    @staticmethod
    def get_grey(tex, fontsize=12, dpi=150):
        import numpy as np
        return np.zeros((10, 10), dtype=np.uint8)


# ─── Added: TexManager methods ──────────────────────────────────────


import os as _os_tex
def _tex_get_basefile(self, tex, fontsize, dpi=None):
    return _os_tex.path.join(self.texcache or '.', f'tex_{abs(hash(tex))}')

def _tex_get_custom_preamble(self):  return getattr(self, 'custom_preamble', '')
def _tex_get_font_preamble(self):    return ''
def _tex_get_rgba(self, tex, fontsize=10, dpi=80, rgb=(0, 0, 0)):
    import numpy as _np
    return _np.zeros((10, 10, 4))
def _tex_make_dvi(self, tex, fontsize):
    return self.get_basefile(tex, fontsize) + '.dvi'
def _tex_make_png(self, tex, fontsize, dpi):
    return self.get_basefile(tex, fontsize) + '.png'
def _tex_make_tex(self, tex, fontsize):
    return self.get_basefile(tex, fontsize) + '.tex'
def _tex_get_text_width_height_descent(self, tex, fontsize, renderer=None):
    return 0, 0, 0

try:
    TexManager
except NameError:
    class TexManager:
        texcache = '.'
        def __init__(self): pass

TexManager.get_basefile         = _tex_get_basefile
TexManager.get_custom_preamble  = _tex_get_custom_preamble
TexManager.get_font_preamble    = _tex_get_font_preamble
TexManager.get_rgba             = _tex_get_rgba
TexManager.make_dvi             = _tex_make_dvi
TexManager.make_png             = _tex_make_png
TexManager.make_tex             = _tex_make_tex
TexManager.get_text_width_height_descent = _tex_get_text_width_height_descent


# ─── Added: stub methods to match upstream class surface ────────
def _attach_remaining_stubs():
    def _stub(self, *a, **kw): return None
    if not hasattr(TexManager, 'texcache'): TexManager.texcache = _stub
_attach_remaining_stubs()
